const contact=document.querySelector('#contact');
const projectDialog=document.querySelector('#project-dialog');
function openDialog(dialog){if(projectDialog.open)projectDialog.close();dialog.showModal();document.body.classList.add('modal-open');}
document.querySelectorAll('[data-contact]').forEach(button=>button.addEventListener('click',()=>openDialog(contact)));
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('modal-open'));dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});});
document.querySelector('#contact-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);const subject='Project enquiry — '+data.get('name');const body=`Hello Code Constellation,\n\n${data.get('brief')}\n\nName: ${data.get('name')}\nEmail: ${data.get('email')}`;window.location.href=`mailto:codeconstellation.business@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;});
const projects=[["Client work · Investor storytelling", "1Xircle", "An AI-powered stokvel platform in South Africa needed to explain its product to investors quickly. We connected the investor pitch deck, a 60-second explainer and logo clean-up. The deck supported a successful investor meeting, and the reviewer rated the work 10/10. Cover art is illustrative; the commissioned materials are not displayed here."], ["Concept · Brand exploration", "Poppio", "An independent concept exploration. The product brief, deliverables and case study details are being prepared. This cover is an illustrative visual direction."], ["Unofficial concept · Product storytelling", "Tesla Roadster", "An independent improvement concept for the Roadster product page, exploring storytelling for a premium launch. Not commissioned by or affiliated with Tesla. Cover art illustrates the direction rather than a finished website screenshot."], ["Concept · Creative exploration", "Vespera", "An independent concept exploration. The brief, deliverables and case study details are being prepared. This cover is an illustrative visual direction."], ["Unofficial concept · Cinematic brand experience", "Ferrari F1", "An independent cinematic team-site concept exploring motion, speed and racing storytelling. Not commissioned by or affiliated with Ferrari or Formula One. Cover art illustrates the concept direction."], ["Lab · Interactive 3D", "Sanjai creative portfolio", "A personal creative portfolio built around an interactive 3D head. An exploration of real-time 3D and interaction craft. Technical details and interaction documentation are being prepared; the cover is illustrative."]];
document.querySelectorAll('[data-project]').forEach(button=>button.addEventListener('click',()=>{const [type,title,description]=projects[Number(button.dataset.project)];document.querySelector('#project-type').textContent=type;document.querySelector('#project-title').textContent=title;document.querySelector('#project-description').textContent=description;openDialog(projectDialog);}));
document.querySelectorAll('.service-list details').forEach(item=>item.addEventListener('toggle',()=>{if(item.open)document.querySelectorAll('.service-list details').forEach(other=>{if(other!==item)other.open=false;});}));

const proofCards=[...document.querySelectorAll('.proof-card')];
let proofIndex=0,proofBusy=false;
function arrangeProof(){proofCards.forEach((card,i)=>{const order=(i-proofIndex+proofCards.length)%proofCards.length;card.style.zIndex=String(proofCards.length-order);card.inert=order!==0;card.setAttribute('aria-hidden',String(order!==0));const rotation=order===0?0:[-7,6,-5,8][(order-1)%4];if(window.gsap)gsap.set(card,{rotation,yPercent:0});else card.style.transform=`rotate(${rotation}deg)`;});document.querySelector('#deck-count').textContent=`${String(proofIndex+1).padStart(2,'0')} / 05`;}
function moveProof(direction){if(proofBusy)return;const outgoing=proofCards[proofIndex];const next=(proofIndex+direction+proofCards.length)%proofCards.length;if(!window.gsap||matchMedia('(prefers-reduced-motion: reduce)').matches){proofIndex=next;arrangeProof();return;}proofBusy=true;gsap.to(outgoing,{yPercent:direction>0?-125:125,rotation:direction*12,duration:.32,ease:'power2.in',onComplete:()=>{proofIndex=next;arrangeProof();gsap.fromTo(proofCards[next],{rotation:direction*-7,scale:.97},{rotation:0,scale:1,duration:.55,ease:'back.out(1.4)'});proofBusy=false;}});}
if(proofCards.length){arrangeProof();document.querySelector('[data-deck-next]').addEventListener('click',()=>moveProof(1));document.querySelector('[data-deck-prev]').addEventListener('click',()=>moveProof(-1));let touchStart=0;const deck=document.querySelector('.proof-deck');deck.addEventListener('touchstart',e=>{touchStart=e.changedTouches[0].clientX;},{passive:true});deck.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>50)moveProof(delta<0?1:-1);},{passive:true});}
